/* ==========================================================================
 *  导出
 * ========================================================================== */
const PRESET_FORCE_TEMPLATES = [
  XIANXIA_FORCES,
  WARCRAFT_FORCES,
  PREHISTORIC_FORCES,
  ISEKAI_FORCES,
  DND_FORCES,
]

export default PRESET_FORCE_TEMPLATES

/** 快速获取模板列表 */
export function getForceTemplateList() {
  return PRESET_FORCE_TEMPLATES.map((t) => ({
    key: t.templateKey,
    name: t.templateName,
    icon: t.templateIcon,
    tags: t.templateTags,
    desc: t.templateDesc,
    // 不同模板字段略有不同，统一用字段 len
    forceCount: (t.forces || t.factions || []).length,
  }))
}

/** 按 key 获取模板 */
export function getForceTemplateByKey(key) {
  const tpl = PRESET_FORCE_TEMPLATES.find((t) => t.templateKey === key)
  if (!tpl) return null
  // 兼容旧版 factions 字段
  const arr = tpl.forces || tpl.factions || []
  return { ...tpl, forces: arr }
}

/** 名称映射 */
export function getForceTemplateMap() {
  return Object.fromEntries(
    PRESET_FORCE_TEMPLATES.map((t) => [t.templateKey, { name: t.templateName, icon: t.templateIcon }])
  )
}
